insert into public.lessons (id, topic_id, subject_id, curriculum_version_id, grade, title, estimated_minutes, objectives, sections, key_terms, provenance, review_status, sort_order) values
  ('g8-math-algebra-l1', 'g8-math-algebra', 'mathematics', 'liblearn-v1', 8, 'Understanding Variables and Expressions', 12, '[{"id":"o1","text":"Explain what a variable stands for in an expression."},{"id":"o2","text":"Write a word problem as an algebraic expression."},{"id":"o3","text":"Identify the terms and coefficients in an expression."}]'::jsonb, '[{"heading":"What a variable is","body":"A variable is a letter that stands in for a number you do not know yet. In the expression 3x + 5, the letter x is the variable. It has no fixed value - it waits for you to find out what it is. The number 3 in front of it is called the coefficient, and it means \"three lots of x\".","example":"If a bundle of cassava costs x dollars, then 3 bundles cost 3x dollars. When x turns out to be 25, the three bundles cost 3 x 25 = 75 dollars."},{"heading":"Terms and coefficients","body":"An expression is built from terms separated by plus or minus signs. In 4a + 7b - 2, there are three terms: 4a, 7b and -2. The coefficient of a is 4 and the coefficient of b is 7. The term -2 has no variable at all, so it is called a constant - its value never changes."},{"heading":"Turning words into algebra","body":"Most of algebra is translation. \"Five more than a number\" becomes n + 5. \"Twice a number, less three\" becomes 2n - 3. Read the sentence slowly and write down each piece in the order it appears, then check that your expression says the same thing as the words.","example":"A taxi charges 40 dollars to start plus 15 dollars for each kilometre. The cost of a journey of k kilometres is 40 + 15k."}]'::jsonb, '[]'::jsonb, 'liblearn', 'published', 1)
insert into public.lessons (id, topic_id, subject_id, curriculum_version_id, grade, title, estimated_minutes, objectives, sections, key_terms, provenance, review_status, sort_order) values
  ('g8-math-algebra-l2', 'g8-math-algebra', 'mathematics', 'liblearn-v1', 8, 'Solving Linear Equations', 15, '[{"id":"o1","text":"Solve a one-step linear equation."},{"id":"o2","text":"Solve a two-step linear equation."},{"id":"o3","text":"Check a solution by substituting it back."}]'::jsonb, '[{"heading":"The balance rule","body":"An equation says two things are equal. Picture a balance scale: whatever you do to one side, you must do to the other, or the scale tips. That single rule is the whole of equation solving. To get x by itself, undo whatever has been done to it - and do the same undoing on both sides.","example":"x + 7 = 12. Seven has been added to x, so subtract 7 from both sides: x + 7 - 7 = 12 - 7, giving x = 5."},{"heading":"Two-step equations","body":"When x has been multiplied and then added to, undo in reverse order: deal with the addition or subtraction first, then the multiplication. This is the opposite of the order you would use to build the expression up.","example":"3x + 4 = 19. First subtract 4 from both sides: 3x = 15. Then divide both sides by 3: x = 5."},{"heading":"Always check your answer","body":"Substituting your answer back into the original equation costs ten seconds and catches almost every mistake. Put the number in place of the letter and work out both sides separately. If they match, you are right.","example":"Check x = 5 in 3x + 4 = 19. Left side: 3 x 5 + 4 = 15 + 4 = 19. Right side: 19. They match, so x = 5 is correct."}]'::jsonb, '[]'::jsonb, 'liblearn', 'published', 2)
insert into public.lessons (id, topic_id, subject_id, curriculum_version_id, grade, title, estimated_minutes, objectives, sections, key_terms, provenance, review_status, sort_order) values
  ('g8-math-algebra-l3', 'g8-math-algebra', 'mathematics', 'liblearn-v1', 8, 'Equations with Brackets', 14, '[{"id":"o1","text":"Expand a bracket using the distributive law."},{"id":"o2","text":"Solve an equation that contains brackets."}]'::jsonb, '[{"heading":"Expanding brackets","body":"The number outside a bracket multiplies everything inside it - every term, not just the first. This is the distributive law. Missing the second term is the single most common slip in this topic, so write the multiplication out in full until it becomes automatic.","example":"4(x + 3) means 4 times x plus 4 times 3, which is 4x + 12. It does not mean 4x + 3."},{"heading":"Solving with brackets","body":"Expand the bracket first, then solve the equation the ordinary way with the balance rule. Take care with a minus sign outside a bracket: it changes the sign of every term inside.","example":"2(x - 5) = 14. Expand: 2x - 10 = 14. Add 10 to both sides: 2x = 24. Divide by 2: x = 12."}]'::jsonb, '[]'::jsonb, 'liblearn', 'published', 3)
insert into public.lessons (id, topic_id, subject_id, curriculum_version_id, grade, title, estimated_minutes, objectives, sections, key_terms, provenance, review_status, sort_order) values
  ('g8-math-fractions-l1', 'g8-math-fractions', 'mathematics', 'liblearn-v1', 8, 'Converting Fractions and Decimals', 11, '[{"id":"o1","text":"Convert a fraction to a decimal by division."},{"id":"o2","text":"Convert a terminating decimal to a fraction in lowest terms."}]'::jsonb, '[{"heading":"Fraction to decimal","body":"A fraction is a division waiting to happen. The line between the numbers means \"divide\". So to turn a fraction into a decimal, divide the top number by the bottom number.","example":"3/4 means 3 divided by 4, which is 0.75. And 1/8 means 1 divided by 8, which is 0.125."},{"heading":"Decimal to fraction","body":"Read the decimal aloud and the fraction is usually in the words. 0.7 is \"seven tenths\", so it is 7/10. 0.35 is \"thirty-five hundredths\", so it is 35/100 - then cancel down to 7/20 by dividing top and bottom by 5."}]'::jsonb, '[]'::jsonb, 'liblearn', 'published', 1)
insert into public.lessons (id, topic_id, subject_id, curriculum_version_id, grade, title, estimated_minutes, objectives, sections, key_terms, provenance, review_status, sort_order) values
  ('g6-math-fractions-l1', 'g6-math-fractions', 'mathematics', 'liblearn-v1', 6, 'Naming and Comparing Fractions', 10, '[{"id":"o1","text":"Name the numerator and denominator of a fraction."},{"id":"o2","text":"Compare two fractions with the same denominator."}]'::jsonb, '[{"heading":"The two numbers","body":"A fraction has a top number and a bottom number. The bottom number - the denominator - tells you how many equal parts the whole has been cut into. The top number - the numerator - tells you how many of those parts you have.","example":"If a loaf is cut into 8 equal slices and you take 3, you have 3/8 of the loaf. The 8 is the denominator, the 3 is the numerator."},{"heading":"Comparing fractions","body":"When two fractions have the same denominator, the pieces are the same size, so the one with the bigger numerator is bigger. 5/8 is greater than 3/8 because five equal pieces beat three of the same size."}]'::jsonb, '[]'::jsonb, 'liblearn', 'published', 1)
insert into public.lessons (id, topic_id, subject_id, curriculum_version_id, grade, title, estimated_minutes, objectives, sections, key_terms, provenance, review_status, sort_order) values
  ('g8-science-matter-l1', 'g8-science-matter', 'general-science', 'liblearn-v1', 8, 'The Three States of Matter', 12, '[{"id":"o1","text":"Describe the arrangement of particles in solids, liquids and gases."},{"id":"o2","text":"Explain why a gas fills its container but a solid does not."}]'::jsonb, '[{"heading":"Particles and arrangement","body":"All matter is made of tiny particles. What makes a solid different from a liquid or a gas is not the particles themselves but how they are arranged and how freely they move. In a solid they are packed closely in a fixed pattern and can only vibrate. In a liquid they are still close together but can slide past one another. In a gas they are far apart and move quickly in all directions."},{"heading":"Shape and volume","body":"Because solid particles hold their positions, a solid keeps its own shape and volume. A liquid keeps its volume but takes the shape of its container, since its particles can flow. A gas keeps neither - its particles spread out until they fill whatever space they are given.","example":"Water shows all three. Ice holds its shape. Liquid water takes the shape of the cup. Steam spreads through the whole kitchen."}]'::jsonb, '[]'::jsonb, 'liblearn', 'published', 1)
insert into public.lessons (id, topic_id, subject_id, curriculum_version_id, grade, title, estimated_minutes, objectives, sections, key_terms, provenance, review_status, sort_order) values
  ('g8-english-speech-l1', 'g8-english-speech', 'english', 'liblearn-v1', 8, 'Nouns, Verbs and Adjectives', 10, '[{"id":"o1","text":"Identify nouns, verbs and adjectives in a sentence."},{"id":"o2","text":"Explain the job each does."}]'::jsonb, '[{"heading":"The three workhorses","body":"A noun names something - a person, place, thing or idea. A verb tells you what is happening or what something is. An adjective describes a noun, adding detail about which one, what kind or how many.","example":"In \"The clever student answered quickly\", student is the noun, answered is the verb, and clever is the adjective describing the student."},{"heading":"Finding them reliably","body":"To find the verb, ask what is being done. To find the noun, ask who or what is doing it. To find adjectives, look at the words sitting just before a noun and ask whether they describe it."}]'::jsonb, '[]'::jsonb, 'liblearn', 'published', 1)
insert into public.lessons (id, topic_id, subject_id, curriculum_version_id, grade, title, estimated_minutes, objectives, sections, key_terms, provenance, review_status, sort_order) values
  ('g10-bio-cells-l1', 'g10-bio-cells', 'biology', 'liblearn-v1', 10, 'Cell Structure and Organelles', 16, '[{"id":"o1","text":"Name the main organelles of a plant and an animal cell."},{"id":"o2","text":"State the function of the nucleus, mitochondria and chloroplast."},{"id":"o3","text":"Describe two differences between plant and animal cells."}]'::jsonb, '[{"heading":"The cell as a working unit","body":"Every living thing is built from cells, and each cell is a small working unit with parts called organelles. Each organelle has a job, and the cell stays alive because they work together."},{"heading":"The main organelles","body":"The nucleus holds the cell’s genetic information and controls its activities. The mitochondria release energy from food through respiration. The cell membrane controls what enters and leaves. The cytoplasm is the jelly where most reactions happen.","example":"Muscle cells contain very many mitochondria, because contracting a muscle demands a great deal of energy."},{"heading":"Plant cells are different","body":"Plant cells have three parts animal cells do not: a rigid cell wall made of cellulose that gives the cell its shape, chloroplasts containing chlorophyll where photosynthesis takes place, and a large permanent vacuole filled with cell sap that helps keep the cell firm."}]'::jsonb, '[]'::jsonb, 'liblearn', 'published', 1)
insert into public.lessons (id, topic_id, subject_id, curriculum_version_id, grade, title, estimated_minutes, objectives, sections, key_terms, provenance, review_status, sort_order) values
  ('g11-math-quadratics-l1', 'g11-math-quadratics', 'mathematics', 'liblearn-v1', 11, 'Solving Quadratic Equations by Factorising', 15, '[{"id":"o1","text":"Recognise a quadratic equation and write it in standard form."},{"id":"o2","text":"Factorise a quadratic expression into two brackets."},{"id":"o3","text":"Use the zero-product rule to find both solutions."}]'::jsonb, '[{"heading":"What you will learn","body":"By the end of this lesson you will be able to take a quadratic equation, rearrange it into standard form, factorise it, and read off both of its roots. Factorising is the fastest method when it works, so it is worth trying first."},{"heading":"Introduction","body":"A linear equation like 3x + 4 = 19 has exactly one solution. A quadratic is different: because the unknown is squared, there are usually two values of x that satisfy it.\n\nThink about x² = 9. It is tempting to answer 3 and stop. But (−3)² = 9 as well, so x = 3 and x = −3 both work. Losing the second solution is the single most common mistake with quadratics, and factorising is a method that hands you both."},{"heading":"Getting to standard form","body":"Before you can factorise, every term must be on one side with zero on the other:\n\n    ax² + bx + c = 0\n\nIf you are given x² + 5x = −6, add 6 to both sides to get x² + 5x + 6 = 0. Only now is it ready.\n\nThis step is not a formality. The method that follows depends on one side being exactly zero, and it gives wrong answers if it is not."},{"heading":"Factorising","body":"To factorise x² + bx + c, look for two numbers that MULTIPLY to give c and ADD to give b.\n\nFor x² + 5x + 6: you need two numbers multiplying to 6 and adding to 5.\n\n    1 × 6 = 6, but 1 + 6 = 7   ✗\n    2 × 3 = 6, and 2 + 3 = 5   ✓\n\nSo the numbers are 2 and 3, and the expression factorises as (x + 2)(x + 3).\n\nWatch the signs. If c is positive and b is negative, both numbers are negative: x² − 5x + 6 = (x − 2)(x − 3). If c is negative, one number is positive and the other negative.","example":"Factorise x² − x − 12.\n\nTwo numbers multiplying to −12, adding to −1.\nSince −12 is negative, one is positive and one negative.\n\n    3 and −4:  3 × (−4) = −12 ✓   3 + (−4) = −1 ✓\n\nSo x² − x − 12 = (x + 3)(x − 4)."},{"heading":"From factors to roots","body":"Here is the step that makes the whole method work. If two quantities multiply to give zero, then at least one of them MUST be zero — there is no other way to get a product of zero.\n\nSo from (x + 2)(x + 3) = 0 we get:\n\n    x + 2 = 0   →   x = −2\n    x + 3 = 0   →   x = −3\n\nBoth are solutions. Notice the sign flip: the bracket (x + 2) gives the root −2, not +2. Students lose marks on this more often than on the factorising itself."},{"heading":"Worked example","body":"Solve x² + 2x − 15 = 0 completely.","example":"Step 1 — Already in standard form.\n\nStep 2 — Two numbers multiplying to −15, adding to +2.\n    5 × (−3) = −15 ✓    5 + (−3) = 2 ✓\n\nStep 3 — Factorise:\n    (x + 5)(x − 3) = 0\n\nStep 4 — Set each bracket to zero:\n    x + 5 = 0  →  x = −5\n    x − 3 = 0  →  x = 3\n\nStep 5 — Check by substituting back:\n    x = −5:  25 − 10 − 15 = 0 ✓\n    x = 3:   9 + 6 − 15 = 0 ✓\n\nAnswer: x = −5 or x = 3"},{"heading":"Try it yourself","body":"Solve these, and check each answer by substituting it back in:\n\n  1. x² + 7x + 10 = 0\n  2. x² − 9x + 20 = 0\n  3. x² − 16 = 0   (hint: what is b here?)\n\nIf you get stuck, ask the AI Tutor for a hint rather than the answer — you will remember the method far better for having worked it out."},{"heading":"Summary","body":"• Rearrange into ax² + bx + c = 0 first — always.\n• Find two numbers multiplying to c and adding to b.\n• Write the two brackets, set each to zero, solve each.\n• The bracket (x + k) gives the root x = −k. Mind the sign.\n• Expect two solutions, and check both.\n\nNot every quadratic factorises neatly. When no whole numbers work, use the quadratic formula instead — that is the next lesson."}]'::jsonb, '[{"term":"Quadratic equation","definition":"An equation in which the highest power of the unknown is 2."},{"term":"Standard form","definition":"A quadratic written as ax² + bx + c = 0, with everything on one side."},{"term":"Root","definition":"A value of x that makes the equation true. A quadratic has at most two."},{"term":"Zero-product rule","definition":"If two things multiply to give 0, at least one of them must be 0."}]'::jsonb, 'liblearn', 'published', 1)
insert into public.lessons (id, topic_id, subject_id, curriculum_version_id, grade, title, estimated_minutes, objectives, sections, key_terms, provenance, review_status, sort_order) values
  ('g11-math-quadratics-l2', 'g11-math-quadratics', 'mathematics', 'liblearn-v1', 11, 'The Quadratic Formula and the Discriminant', 15, '[{"id":"o1","text":"Apply the quadratic formula to any quadratic equation."},{"id":"o2","text":"Calculate the discriminant and say how many roots exist."},{"id":"o3","text":"Choose sensibly between factorising and the formula."}]'::jsonb, '[{"heading":"What you will learn","body":"Factorising is quick but only works when the numbers are friendly. The quadratic formula works every time, on every quadratic, without exception. You will also learn to tell in advance — before solving anything — how many solutions an equation has."},{"heading":"The formula","body":"For any equation in the form ax² + bx + c = 0:\n\n    x = ( −b ± √(b² − 4ac) ) / 2a\n\nThe ± is doing important work: it is what produces the two roots. Take the + once, the − once, and you have both.\n\nTo use it, first identify a, b and c including their signs. For 2x² − 7x + 3 = 0: a = 2, b = −7, c = 3. Note that b is −7, not 7. Dropping that minus sign is the most frequent source of wrong answers here."},{"heading":"Worked example","body":"Solve 2x² − 7x + 3 = 0 using the formula.","example":"a = 2,  b = −7,  c = 3\n\nDiscriminant first:\n    b² − 4ac = (−7)² − 4(2)(3)\n             = 49 − 24\n             = 25\n\n√25 = 5, a whole number, so this one would have factorised too.\n\nNow the formula:\n    x = ( −(−7) ± 5 ) / (2 × 2)\n    x = ( 7 ± 5 ) / 4\n\nTaking + :  x = 12/4 = 3\nTaking − :  x = 2/4 = 0.5\n\nAnswer: x = 3 or x = 0.5\n\nCheck x = 3:  2(9) − 7(3) + 3 = 18 − 21 + 3 = 0 ✓"},{"heading":"The discriminant","body":"The part under the square root, b² − 4ac, is called the discriminant. Calculate it on its own and it tells you what to expect:\n\n    b² − 4ac > 0  →  two different real roots\n    b² − 4ac = 0  →  one repeated root\n    b² − 4ac < 0  →  no real roots\n\nThe reason is the square root. A positive number has two square roots, so ± gives two answers. Zero has one, so both branches collapse to the same value. A negative number has no real square root at all, which is why the graph never crosses the x-axis.\n\nThis is worth a moment on its own: it lets you answer \"how many solutions does this have?\" without solving anything."},{"heading":"Which method should you use?","body":"Try factorising first. If you spot the two numbers within about fifteen seconds, factorising is faster and less error-prone.\n\nUse the formula when the numbers do not cooperate, when a ≠ 1, or when the question asks for answers to a number of decimal places — that is a strong hint the roots are not whole numbers.\n\nThe formula is never wrong, only sometimes slower. If you are unsure, use it."},{"heading":"Try it yourself","body":"1. Solve x² + 4x + 1 = 0 to 2 decimal places.\n2. How many real roots does x² + 2x + 5 = 0 have? Find the discriminant — you should not need to solve it.\n3. Solve 3x² − 5x − 2 = 0."},{"heading":"Summary","body":"• x = (−b ± √(b² − 4ac)) / 2a works for every quadratic.\n• Identify a, b, c carefully, keeping negative signs attached.\n• The discriminant b² − 4ac tells you the number of real roots before you solve.\n• Factorise when it is quick; use the formula whenever it is not."}]'::jsonb, '[{"term":"Quadratic formula","definition":"x = (−b ± √(b² − 4ac)) / 2a — solves any quadratic in standard form."},{"term":"Discriminant","definition":"The quantity b² − 4ac, which reveals how many real roots an equation has."},{"term":"Coefficient","definition":"The number multiplying a term: in 3x², the coefficient a is 3."}]'::jsonb, 'liblearn', 'published', 2)
insert into public.lessons (id, topic_id, subject_id, curriculum_version_id, grade, title, estimated_minutes, objectives, sections, key_terms, provenance, review_status, sort_order) values
  ('g11-math-trigonometry-l1', 'g11-math-trigonometry', 'mathematics', 'liblearn-v1', 11, 'Sine, Cosine and Tangent in Right-Angled Triangles', 14, '[{"id":"o1","text":"Label the hypotenuse, opposite and adjacent sides correctly."},{"id":"o2","text":"Use SOH-CAH-TOA to choose the right ratio."},{"id":"o3","text":"Find an unknown side or angle in a right-angled triangle."}]'::jsonb, '[{"heading":"What you will learn","body":"Trigonometry lets you find a distance or an angle you cannot physically measure — the height of a tree, the width of a river, the angle of a roof — using only a triangle and a calculator."},{"heading":"Labelling the sides","body":"Every right-angled triangle has three sides, and which name each one takes depends on the angle you are working from.\n\n• The HYPOTENUSE is the longest side, opposite the right angle. It never changes.\n• The OPPOSITE is the side directly facing your chosen angle.\n• The ADJACENT is the remaining side, touching your angle.\n\nOnly the hypotenuse is fixed. If you switch to the other non-right angle, opposite and adjacent swap places. Label the sides for the angle in the question before doing anything else."},{"heading":"SOH-CAH-TOA","body":"Three ratios connect an angle to two sides:\n\n    sin θ = Opposite / Hypotenuse      (SOH)\n    cos θ = Adjacent / Hypotenuse      (CAH)\n    tan θ = Opposite / Adjacent        (TOA)\n\nTo choose: identify which two sides the question involves — the one you know and the one you want — and pick the ratio containing exactly those two."},{"heading":"Worked example — finding a side","body":"A ladder leans against a wall at 65° to the ground. The ladder is 4 m long. How high up the wall does it reach?","example":"The angle is 65°. The height up the wall is OPPOSITE that angle.\nThe ladder is the HYPOTENUSE (4 m).\n\nOpposite and hypotenuse → sine.\n\n    sin 65° = opposite / 4\n    opposite = 4 × sin 65°\n    opposite = 4 × 0.9063\n    opposite = 3.63 m (2 d.p.)\n\nSanity check: 3.63 m is less than the 4 m ladder, which it must be."},{"heading":"Worked example — finding an angle","body":"A ramp rises 1.5 m over a horizontal distance of 6 m. What angle does it make with the ground?","example":"Rise = 1.5 m is OPPOSITE the angle.\nHorizontal 6 m is ADJACENT.\n\nOpposite and adjacent → tangent.\n\n    tan θ = 1.5 / 6 = 0.25\n\nTo get θ from tan θ, use the inverse (tan⁻¹ on your calculator):\n\n    θ = tan⁻¹(0.25) = 14.0°\n\nA gentle slope, which matches a ramp."},{"heading":"Try it yourself","body":"1. A triangle has hypotenuse 10 cm and an angle of 30°. Find the side opposite that angle.\n2. A tree casts a 12 m shadow when the sun is 40° above the horizon. How tall is the tree?\n3. A right-angled triangle has opposite 5 and adjacent 12. Find the angle."},{"heading":"Summary","body":"• Label opposite, adjacent and hypotenuse relative to the angle in the question.\n• Pick the ratio containing the side you know and the side you want.\n• Multiply when finding a side; use sin⁻¹, cos⁻¹ or tan⁻¹ when finding an angle.\n• Check your answer is physically sensible — the hypotenuse is always longest."}]'::jsonb, '[{"term":"Hypotenuse","definition":"The longest side, always opposite the right angle."},{"term":"Opposite","definition":"The side facing the angle you are working with."},{"term":"Adjacent","definition":"The side next to your angle that is not the hypotenuse."}]'::jsonb, 'liblearn', 'published', 1)
insert into public.lessons (id, topic_id, subject_id, curriculum_version_id, grade, title, estimated_minutes, objectives, sections, key_terms, provenance, review_status, sort_order) values
  ('g11-bio-photosynthesis-l1', 'g11-bio-photosynthesis', 'biology', 'liblearn-v1', 11, 'How Photosynthesis Works', 14, '[{"id":"o1","text":"State the word and balanced equations for photosynthesis."},{"id":"o2","text":"Explain the role of chlorophyll, light, water and carbon dioxide."},{"id":"o3","text":"Describe the limiting factors that control the rate."}]'::jsonb, '[{"heading":"What you will learn","body":"Photosynthesis is how nearly all food on Earth begins. You will learn what goes in, what comes out, where in the leaf it happens, and what controls how fast it runs."},{"heading":"Introduction","body":"Animals eat. Plants cannot — so they build their own food instead, out of air, water and sunlight.\n\nThis matters beyond botany. Every animal either eats plants or eats something that ate plants, and the oxygen you are breathing right now was released by photosynthesis. It is the entry point of energy into almost every food chain."},{"heading":"The equation","body":"In words:\n\n    carbon dioxide + water → glucose + oxygen\n                (in the presence of light and chlorophyll)\n\nBalanced:\n\n    6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂\n\nRead what this says. The plant takes two low-energy substances and builds one high-energy one. Light supplies the energy for that; chlorophyll captures the light. Neither is consumed as a raw material, which is why both are written above the arrow rather than in it.\n\nOxygen is a by-product. The plant does not make it deliberately — it is simply left over."},{"heading":"Where it happens","body":"Photosynthesis occurs in CHLOROPLASTS, concentrated in the palisade layer near the upper surface of the leaf where light is strongest.\n\nA leaf is well built for the job:\n• Broad and flat — large surface area for catching light.\n• Thin — gases diffuse across a short distance.\n• Stomata on the underside — let CO₂ in and O₂ out.\n• Veins — deliver water from the roots, carry glucose away.\n\nEach feature is a solution to a supply problem: light, gas, water or transport."},{"heading":"Limiting factors","body":"Three things control the rate, and at any moment ONE of them is holding the process back — whichever is in shortest supply. That one is the limiting factor.\n\n• LIGHT INTENSITY — more light, faster rate, until another factor takes over.\n• CARBON DIOXIDE CONCENTRATION — usually the limiting factor outdoors, since air is only about 0.04% CO₂.\n• TEMPERATURE — raises the rate up to an optimum, then the rate falls sharply as enzymes denature.\n\nThe temperature curve behaves differently from the other two, and examiners like this point. Light and CO₂ level off at a plateau. Temperature rises, peaks, then DROPS — because enzymes are proteins and heat destroys their shape permanently.","example":"Interpreting a rate-against-light-intensity graph:\n\nThe steep early section — light is limiting. Adding light adds rate.\n\nThe flat plateau — light is no longer limiting. Something else (CO₂ or temperature) has become the cap, so extra light changes nothing.\n\nExam technique: if a graph plateaus, do not answer \"the plant has enough light\". Say which factor has BECOME limiting instead."},{"heading":"Try it yourself","body":"1. Write the balanced equation from memory, then check it.\n2. A farmer grows tomatoes in a greenhouse and adds CO₂ to the air. Why might this increase yield — and when would it make no difference at all?\n3. Explain why a plant kept in constant darkness dies even though it still has water and CO₂."},{"heading":"Summary","body":"• 6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂, requiring light and chlorophyll.\n• It happens in chloroplasts, mainly in the palisade layer.\n• Leaf structure solves the supply problems of light, gas and water.\n• Light, CO₂ and temperature can each limit the rate.\n• Only temperature causes the rate to FALL past the optimum, because enzymes denature."}]'::jsonb, '[{"term":"Photosynthesis","definition":"The process by which green plants make glucose from carbon dioxide and water using light energy."},{"term":"Chlorophyll","definition":"The green pigment in chloroplasts that absorbs light energy."},{"term":"Chloroplast","definition":"The organelle in plant cells where photosynthesis takes place."},{"term":"Stomata","definition":"Small pores, mostly on the underside of a leaf, that let gases in and out."},{"term":"Limiting factor","definition":"The factor in shortest supply, which alone caps the rate of a process."}]'::jsonb, 'liblearn', 'published', 1)
insert into public.lessons (id, topic_id, subject_id, curriculum_version_id, grade, title, estimated_minutes, objectives, sections, key_terms, provenance, review_status, sort_order) values
  ('g11-bio-genetics-l1', 'g11-bio-genetics', 'biology', 'liblearn-v1', 11, 'Genes, Alleles and Monohybrid Crosses', 16, '[{"id":"o1","text":"Distinguish gene, allele, genotype and phenotype."},{"id":"o2","text":"Explain dominant and recessive inheritance."},{"id":"o3","text":"Complete a Punnett square and state the expected ratio."}]'::jsonb, '[{"heading":"What you will learn","body":"Why children resemble their parents without being identical to them — and how to predict, with real numbers, what a cross will produce."},{"heading":"The vocabulary matters","body":"Genetics questions are lost on vocabulary more than on reasoning, so be precise:\n\nA GENE is the instruction for a characteristic — say, height in a pea plant.\nAn ALLELE is a version of that instruction — tall, or short.\n\nYou carry two alleles for each gene: one from each parent. Together they are your GENOTYPE. What you actually look like is your PHENOTYPE.\n\nThe distinction is the whole subject in miniature: two organisms can look identical and carry different alleles. TT and Tt are both tall, but they do not breed the same way."},{"heading":"Dominant and recessive","body":"A DOMINANT allele shows in the phenotype whenever it is present, even in a single copy. Capital letter: T.\n\nA RECESSIVE allele shows ONLY when no dominant allele is present — so both must be recessive. Lower case: t.\n\n    TT → tall\n    Tt → tall   (the T masks the t)\n    tt → short\n\nSo short plants have exactly one possible genotype, tt. A tall plant could be TT or Tt, and you cannot tell by looking. Use the SAME letter in both cases — T and t, never T and s."},{"heading":"The Punnett square","body":"A Punnett square sets out every way the parents’ alleles can combine.\n\nCross two heterozygous tall plants (Tt × Tt). Each parent passes on either T or t:\n\n            T       t\n        ┌───────┬───────┐\n    T   │  TT   │  Tt   │\n        ├───────┼───────┤\n    t   │  Tt   │  tt   │\n        └───────┴───────┘\n\nFour equally likely outcomes: TT, Tt, Tt, tt.\n\nGenotype ratio  1 TT : 2 Tt : 1 tt\nPhenotype ratio 3 tall : 1 short\n\nThat 3:1 is the signature of a monohybrid cross between two heterozygotes. Recognising it in a question is often the fastest route to the answer.","example":"A different cross: Tt × tt.\n\n            t       t\n        ┌───────┬───────┐\n    T   │  Tt   │  Tt   │\n        ├───────┼───────┤\n    t   │  tt   │  tt   │\n        └───────┴───────┘\n\nGenotype ratio  2 Tt : 2 tt  →  1 : 1\nPhenotype ratio 1 tall : 1 short\n\nHalf the offspring are short here, where the Tt × Tt cross gave only a quarter. Same alleles, different ratio — which is why you must draw the square rather than recall \"3:1\" by reflex."},{"heading":"Probability, not prophecy","body":"A 3:1 ratio does NOT promise that four offspring will be exactly three tall and one short. It is a probability: each offspring independently has a 3-in-4 chance of being tall.\n\nWith four seeds you might well get four tall ones. With four hundred, the proportion will sit close to 3:1. Large numbers are what make the ratio visible — a point worth stating explicitly when a question asks you to interpret unexpected results."},{"heading":"Try it yourself","body":"1. In pea plants, purple flowers (P) are dominant to white (p). Cross Pp × Pp. Give both ratios.\n2. A white-flowered plant is crossed with a purple one and half the offspring are white. What was the purple parent’s genotype?\n3. Explain why two brown-eyed parents can have a blue-eyed child."},{"heading":"Summary","body":"• Gene = instruction, allele = version, genotype = alleles carried, phenotype = appearance.\n• Dominant shows with one copy; recessive needs two.\n• Use one letter, capital for dominant and lower case for recessive.\n• Tt × Tt gives 3:1; Tt × tt gives 1:1. Draw the square rather than recalling a ratio.\n• Ratios are probabilities and show themselves reliably only in large numbers."}]'::jsonb, '[{"term":"Gene","definition":"A length of DNA coding for one characteristic."},{"term":"Allele","definition":"A version of a gene. You inherit one from each parent."},{"term":"Genotype","definition":"The alleles an organism carries, e.g. Tt."},{"term":"Phenotype","definition":"The characteristic actually shown, e.g. tall."},{"term":"Homozygous","definition":"Two identical alleles (TT or tt)."},{"term":"Heterozygous","definition":"Two different alleles (Tt)."}]'::jsonb, 'liblearn', 'published', 1)
insert into public.lessons (id, topic_id, subject_id, curriculum_version_id, grade, title, estimated_minutes, objectives, sections, key_terms, provenance, review_status, sort_order) values
  ('g11-chem-mole-l1', 'g11-chem-mole', 'chemistry', 'liblearn-v1', 11, 'The Mole: Counting Atoms by Weighing', 16, '[{"id":"o1","text":"Define the mole and state Avogadro’s constant."},{"id":"o2","text":"Convert between mass, moles and number of particles."},{"id":"o3","text":"Calculate molar mass from a chemical formula."}]'::jsonb, '[{"heading":"What you will learn","body":"Chemical reactions happen between individual particles, but no one can count particles. The mole is the bridge: it converts a mass you can weigh into a number of particles you can reason about."},{"heading":"Why chemists need the mole","body":"An equation like 2H₂ + O₂ → 2H₂O is a statement about COUNTS: two hydrogen molecules for every one oxygen molecule.\n\nBut you cannot count molecules in a laboratory. You can only weigh things. And weighing equal masses does not give equal counts, because atoms have different masses — 1 g of hydrogen contains far more atoms than 1 g of lead.\n\nThe mole solves this. It is simply a counting unit for very large numbers, the way \"a dozen\" is a counting unit for twelve.\n\n    1 mole = 6.02 × 10²³ particles\n\nThat number, Avogadro’s constant, is enormous because atoms are tiny. One mole of water is about a mouthful."},{"heading":"Molar mass","body":"Here is the elegant part. The mass of one mole of a substance, in grams, equals its relative atomic or formula mass.\n\n    Carbon:  relative atomic mass 12  →  1 mol weighs 12 g\n    Water:   relative formula mass 18  →  1 mol weighs 18 g\n\nTo find the relative formula mass, add up the atomic masses in the formula:\n\n    H₂O = (2 × 1) + 16 = 18\n    CO₂ = 12 + (2 × 16) = 44\n    CaCO₃ = 40 + 12 + (3 × 16) = 100\n\nSo weighing out 100 g of calcium carbonate gives you exactly one mole of it — 6.02 × 10²³ formula units — without counting anything."},{"heading":"The key equation","body":"Everything in this topic rests on one relationship:\n\n    moles = mass (g) / molar mass (g/mol)\n\nRearranged as needed:\n\n    mass = moles × molar mass\n    molar mass = mass / moles\n\nAnd to reach particles:\n\n    number of particles = moles × 6.02 × 10²³\n\nA reliable habit: write down what you are given, what you want, and which equation connects them, BEFORE substituting numbers."},{"heading":"Worked example","body":"Calculate the number of moles in 25 g of calcium carbonate, CaCO₃, and how many formula units that is.","example":"Step 1 — Molar mass of CaCO₃:\n    Ca = 40\n    C  = 12\n    O₃ = 3 × 16 = 48\n    Total = 100 g/mol\n\nStep 2 — Moles:\n    moles = mass / molar mass\n          = 25 / 100\n          = 0.25 mol\n\nStep 3 — Particles:\n    = 0.25 × 6.02 × 10²³\n    = 1.505 × 10²³ formula units\n\nSanity check: 25 g is a quarter of 100 g, so 0.25 mol. If your answer had come out greater than 1 mol, something went wrong."},{"heading":"Try it yourself","body":"1. How many moles are in 36 g of water (H₂O)?\n2. What is the mass of 2 moles of CO₂?\n3. How many atoms are in 0.5 mol of sodium?\n4. 4.4 g of a gas turns out to be 0.1 mol. What is its molar mass — and can you name the gas?"},{"heading":"Summary","body":"• 1 mole = 6.02 × 10²³ particles.\n• Molar mass in g/mol equals relative formula mass — add the atomic masses.\n• moles = mass / molar mass, rearranged as required.\n• particles = moles × 6.02 × 10²³.\n• Always sanity-check the size of your answer against the molar mass."}]'::jsonb, '[{"term":"Mole","definition":"The amount of substance containing 6.02 × 10²³ particles."},{"term":"Avogadro’s constant","definition":"6.02 × 10²³ — the number of particles in one mole."},{"term":"Molar mass","definition":"The mass of one mole of a substance, in g/mol."},{"term":"Relative atomic mass","definition":"The mass of an atom relative to 1/12 of a carbon-12 atom."}]'::jsonb, 'liblearn', 'published', 1)
insert into public.lessons (id, topic_id, subject_id, curriculum_version_id, grade, title, estimated_minutes, objectives, sections, key_terms, provenance, review_status, sort_order) values
  ('g11-chem-bonding-l1', 'g11-chem-bonding', 'chemistry', 'liblearn-v1', 11, 'Ionic and Covalent Bonding', 15, '[{"id":"o1","text":"Explain why atoms form bonds at all."},{"id":"o2","text":"Describe ionic bonding as transfer and covalent as sharing."},{"id":"o3","text":"Link bonding type to melting point, conductivity and solubility."}]'::jsonb, '[{"heading":"What you will learn","body":"Why atoms bond, the two main ways they do it, and how the bonding explains properties you can observe — why salt melts at 801°C but candle wax melts in your hand."},{"heading":"Why atoms bond","body":"Atoms bond to reach a full outer shell of electrons, which is a more stable, lower-energy arrangement.\n\nThe noble gases already have full outer shells, which is precisely why they are famously unreactive. Every other element achieves the same thing by losing, gaining or sharing electrons.\n\nThat gives two routes:\n• Metal + non-metal → electrons are TRANSFERRED → ionic bonding\n• Non-metal + non-metal → electrons are SHARED → covalent bonding"},{"heading":"Ionic bonding","body":"A metal atom loses its outer electrons; a non-metal gains them. Both end up with full shells, and both are now charged.\n\nSodium chloride:\n    Na has 1 outer electron → loses it → Na⁺\n    Cl has 7 outer electrons → gains 1 → Cl⁻\n\nThe opposite charges attract strongly. Crucially, this is not a bond between one Na⁺ and one particular Cl⁻ — each ion attracts every oppositely charged neighbour, building a giant LATTICE extending in all directions.\n\nThat structure explains the properties:\n• HIGH MELTING POINT — melting means overcoming attractions throughout the whole lattice.\n• CONDUCTS ONLY WHEN MOLTEN OR DISSOLVED — charged ions must be free to move. In a solid they are locked in place, so solid salt does not conduct.\n• BRITTLE — knock the lattice out of alignment and like charges meet, forcing it apart."},{"heading":"Covalent bonding","body":"Two non-metals cannot both gain electrons, so they share instead. A shared PAIR of electrons counts towards the full shell of both atoms.\n\n    H₂  — one shared pair (single bond)\n    O₂  — two shared pairs (double bond)\n    H₂O — oxygen shares with two hydrogens\n\nThe shared pair itself is a strong bond. But most covalent substances exist as small separate MOLECULES, and the forces BETWEEN those molecules are weak.\n\nThis distinction is the most misunderstood point in the topic. When water boils, you are not breaking O–H bonds — you are separating whole water molecules from one another. The bonds inside survive, which is why steam is still H₂O.\n\nHence: low melting and boiling points, and no conductivity, because there are no free charged particles.","example":"Why does sodium chloride melt at 801°C while chlorine gas boils at −34°C, when both involve chlorine?\n\nNaCl — a giant ionic lattice. Melting requires breaking strong attractions between millions of ions. Enormous energy.\n\nCl₂ — small molecules. The Cl–Cl covalent bond is strong, but boiling only has to separate molecules from each other, and the forces between them are weak. Very little energy.\n\nThe lesson: melting and boiling points tell you about the forces BETWEEN particles, not the bonds within them."},{"heading":"Try it yourself","body":"1. Magnesium oxide (MgO) melts at 2852°C. What bonding does it have, and why is its melting point even higher than NaCl’s?\n2. Explain why solid NaCl does not conduct electricity but molten NaCl does.\n3. Predict the bonding in CH₄ and give two expected properties."},{"heading":"Summary","body":"• Atoms bond to achieve full outer shells.\n• Metal + non-metal → transfer → ions → giant lattice.\n• Non-metal + non-metal → sharing → covalent bonds → usually small molecules.\n• Ionic: high melting point, conducts when molten or dissolved, brittle.\n• Covalent molecular: low melting point, does not conduct.\n• Melting point reflects forces BETWEEN particles, not bond strength within them."}]'::jsonb, '[{"term":"Ion","definition":"An atom that has gained or lost electrons and so carries a charge."},{"term":"Ionic bond","definition":"Electrostatic attraction between oppositely charged ions."},{"term":"Covalent bond","definition":"A shared pair of electrons between two atoms."},{"term":"Lattice","definition":"A regular repeating 3-D arrangement of ions."}]'::jsonb, 'liblearn', 'published', 1)
insert into public.lessons (id, topic_id, subject_id, curriculum_version_id, grade, title, estimated_minutes, objectives, sections, key_terms, provenance, review_status, sort_order) values
  ('g11-phys-motion-l1', 'g11-phys-motion', 'physics', 'liblearn-v1', 11, 'Newton''s Three Laws of Motion', 15, '[{"id":"o1","text":"State all three of Newton''s laws correctly."},{"id":"o2","text":"Apply F = ma to calculate force, mass or acceleration."},{"id":"o3","text":"Identify action–reaction pairs correctly."}]'::jsonb, '[{"heading":"What you will learn","body":"Three laws that between them describe the motion of essentially everything you will meet at this level — from a dropped stone to a moving vehicle."},{"heading":"First law — inertia","body":"An object stays at rest, or continues moving at constant velocity in a straight line, UNLESS a resultant force acts on it.\n\nThis contradicts everyday intuition, which says moving things naturally slow down. They do — but only because friction and air resistance are acting. Remove those and motion simply continues.\n\nNote \"resultant\". Forces can act and still cancel. A book on a table has gravity pulling down and the table pushing up equally, so the resultant is zero and the book stays put.\n\nThis is why passengers lurch forward when a vehicle brakes sharply: the vehicle decelerates, but nothing has yet acted on the passenger, who continues at the original speed. That is inertia, and it is the argument for seat belts."},{"heading":"Second law — F = ma","body":"A resultant force produces acceleration in the direction of that force:\n\n    F = m × a\n\n    F in newtons (N), m in kilograms (kg), a in m/s²\n\nOne newton is the force that accelerates 1 kg at 1 m/s².\n\nTwo consequences worth holding onto:\n• The same force on a heavier object gives less acceleration.\n• Acceleration means any change in velocity — speeding up, slowing down, or changing direction.\n\nAlways use the RESULTANT force. If a 1000 N driving force meets 200 N of friction, the resultant is 800 N, and that is what goes into the equation.","example":"A 1200 kg car experiences a 3600 N driving force and 600 N of resistance. Find its acceleration.\n\nResultant force:\n    F = 3600 − 600 = 3000 N\n\nApply F = ma:\n    3000 = 1200 × a\n    a = 3000 / 1200\n    a = 2.5 m/s²\n\nUsing 3600 N instead of the resultant would have given 3 m/s² — a wrong answer that looks perfectly reasonable, which is why the resultant step must be explicit."},{"heading":"Third law — action and reaction","body":"For every action there is an equal and opposite reaction.\n\nStated carefully: if object A exerts a force on object B, then B exerts an equal force on A in the opposite direction.\n\nThe condition students most often miss is that the two forces act on DIFFERENT OBJECTS. That is why they never cancel out — cancelling requires both forces on the same object.\n\nWalking: your foot pushes backward on the ground; the ground pushes forward on you. The forward push on you is what moves you.\n\nA common trap: \"A book rests on a table. Gravity pulls it down, the table pushes it up — are these an action–reaction pair?\" No. Both act on the BOOK. They are balanced forces under the first law. The true partner to the table pushing up on the book is the book pushing down on the table."},{"heading":"Try it yourself","body":"1. A 5 kg object accelerates at 4 m/s². What resultant force acts on it?\n2. A 70 kg person in a lift accelerating upward at 2 m/s² — is the floor’s push greater or less than their weight? Explain.\n3. A rocket works in the vacuum of space with nothing to push against. Use the third law to explain how."},{"heading":"Summary","body":"• First law: no resultant force → velocity unchanged. Inertia.\n• Second law: F = ma, always using the RESULTANT force.\n• Third law: forces come in equal, opposite pairs acting on DIFFERENT objects.\n• Balanced forces on one object ≠ an action–reaction pair."}]'::jsonb, '[{"term":"Force","definition":"A push or pull, measured in newtons (N)."},{"term":"Inertia","definition":"The tendency of an object to resist a change in its motion."},{"term":"Resultant force","definition":"The single force equivalent to all forces acting combined."},{"term":"Acceleration","definition":"Rate of change of velocity, in m/s²."}]'::jsonb, 'liblearn', 'published', 1)
insert into public.lessons (id, topic_id, subject_id, curriculum_version_id, grade, title, estimated_minutes, objectives, sections, key_terms, provenance, review_status, sort_order) values
  ('g11-phys-electricity-l1', 'g11-phys-electricity', 'physics', 'liblearn-v1', 11, 'Current, Voltage, Resistance and Ohm''s Law', 15, '[{"id":"o1","text":"Define current, potential difference and resistance with units."},{"id":"o2","text":"Apply Ohm''s law V = IR."},{"id":"o3","text":"Compare current and voltage in series and parallel circuits."}]'::jsonb, '[{"heading":"What you will learn","body":"The three quantities that describe every circuit, the equation linking them, and how they behave differently in series and parallel arrangements."},{"heading":"The three quantities","body":"CURRENT (I) is the rate at which charge flows, in amperes. Measured with an ammeter connected IN SERIES, so the current passes through it.\n\nPOTENTIAL DIFFERENCE (V), or voltage, is the energy given to each unit of charge, in volts. Measured with a voltmeter connected IN PARALLEL, across the component.\n\nRESISTANCE (R) opposes the flow of current, in ohms. A thin wire has more resistance than a thick one; a long wire more than a short one.\n\nIf an analogy helps: voltage is the pressure pushing water along a pipe, current is how much water flows per second, resistance is how narrow the pipe is. Like all analogies it has limits, but it gets the relationships right."},{"heading":"Ohm''s law","body":"For a component at constant temperature:\n\n    V = I × R\n\nRearranged:\n\n    I = V / R        R = V / I\n\nRead what it says: for a fixed resistance, doubling the voltage doubles the current. For a fixed voltage, doubling the resistance halves it.\n\nThe temperature condition is real. A filament lamp heats up as current flows, its resistance rises, and a V–I graph for it curves instead of staying straight. A component that does keep a straight-line graph is called ohmic — a fixed resistor at steady temperature is the standard example.","example":"A 12 V supply drives current through a 4 Ω resistor. Find the current.\n\n    I = V / R\n    I = 12 / 4\n    I = 3 A\n\nNow add a second 4 Ω resistor in series.\n\n    Total resistance = 4 + 4 = 8 Ω\n    I = 12 / 8 = 1.5 A\n\nThe current halves, because the same voltage now pushes against twice the resistance."},{"heading":"Series and parallel","body":"SERIES — one single path.\n• Current is the SAME everywhere. Charge has nowhere else to go.\n• Voltage DIVIDES between components, adding up to the supply voltage.\n• Resistances add: R = R₁ + R₂\n\nPARALLEL — multiple branches.\n• Voltage is the SAME across each branch, equal to the supply.\n• Current DIVIDES between branches, adding up to the total.\n• Total resistance is LESS than the smallest single resistance.\n\nThat last point surprises people. Adding another parallel branch gives current an additional route, so more current flows in total — which means less overall resistance.\n\nIt is also why house wiring is parallel: every appliance gets the full supply voltage, and switching one off leaves the rest unaffected. In series, one failed bulb would break the only path and everything would go out."},{"heading":"Try it yourself","body":"1. A 9 V battery drives 0.3 A through a lamp. What is its resistance?\n2. Two 6 Ω resistors in series across 12 V — find total resistance and current.\n3. Explain why the V–I graph of a filament lamp curves while that of a fixed resistor is straight."},{"heading":"Summary","body":"• Current (A) = rate of charge flow; ammeter in series.\n• Potential difference (V) = energy per unit charge; voltmeter in parallel.\n• Resistance (Ω) opposes current.\n• V = IR, for constant temperature.\n• Series: current constant, voltage divides, resistances add.\n• Parallel: voltage constant, current divides, total resistance falls."}]'::jsonb, '[{"term":"Current","definition":"Rate of flow of charge, measured in amperes (A)."},{"term":"Potential difference","definition":"Energy transferred per unit charge, measured in volts (V)."},{"term":"Resistance","definition":"Opposition to current flow, measured in ohms (Ω)."}]'::jsonb, 'liblearn', 'published', 1)
insert into public.lessons (id, topic_id, subject_id, curriculum_version_id, grade, title, estimated_minutes, objectives, sections, key_terms, provenance, review_status, sort_order) values
  ('g11-eng-essay-l1', 'g11-eng-essay', 'english', 'liblearn-v1', 11, 'Structuring an Argumentative Essay', 14, '[{"id":"o1","text":"Write a thesis statement that takes a clear position."},{"id":"o2","text":"Build body paragraphs using point, evidence and explanation."},{"id":"o3","text":"Address a counter-argument without weakening your case."}]'::jsonb, '[{"heading":"What you will learn","body":"How to turn an opinion into a structured argument a reader can follow — and how markers actually award credit for it."},{"heading":"Start with a position","body":"An argumentative essay must ARGUE something. The most common weakness is an essay that describes a topic without ever committing to a view.\n\nYour THESIS STATEMENT, usually the final sentence of the introduction, states your position in one sentence.\n\nWeak:  \"This essay will discuss school uniforms.\"\n       — announces a subject, takes no position.\n\nStrong: \"School uniforms should be required because they reduce visible inequality between students, lower costs for families, and cut daily distraction.\"\n       — states a position AND previews three reasons.\n\nThe strong version also does structural work: those three reasons become your three body paragraphs, in that order."},{"heading":"Body paragraphs: P–E–E","body":"Each body paragraph makes ONE point, in three moves:\n\nPOINT — a topic sentence naming the paragraph’s argument.\nEVIDENCE — an example, fact, statistic or quotation supporting it.\nEXPLANATION — how that evidence proves your point and supports the thesis.\n\nThe explanation is where most marks are won and lost. Students frequently state a point, give an example, and stop — leaving the reader to infer the connection. Never make the reader do that work. Spell it out.\n\nOne point per paragraph. If a paragraph needs \"also\" or \"another thing\", it is two paragraphs.","example":"A complete P–E–E paragraph:\n\n[POINT] Uniforms reduce the visible gap between students from different economic backgrounds.\n\n[EVIDENCE] Where ordinary clothes are worn, brand and condition of clothing are immediately visible, and students from poorer households are readily identified by what they can afford.\n\n[EXPLANATION] By removing that signal, a uniform takes one obvious marker of family income out of daily school life. Students are less easily sorted by wealth before they have spoken a word, which supports the argument that uniforms create fairer conditions for learning.\n\nNotice the explanation is the longest part, and that it returns to the thesis."},{"heading":"Handling the other side","body":"A strong essay acknowledges the opposing view. This feels risky but strengthens your case: it shows you have considered the question rather than only one half of it.\n\nThe pattern is concede, then answer:\n\n\"Critics argue that uniforms suppress individual expression. This concern is understandable, but students express identity through many channels beyond clothing, and the fairness gained outweighs a restriction that applies only during school hours.\"\n\nConcede genuinely — do not set up a weak version of the opposing argument to knock over. Then answer it. Never concede without answering, or you have argued against yourself."},{"heading":"The conclusion","body":"A conclusion restates your position in fresh words and draws the argument together. It must not introduce new evidence.\n\nAvoid \"In conclusion, I have discussed…\" — summarising your own structure wastes the most memorable position in the essay. Instead, state what the argument has established and why it matters."},{"heading":"Try it yourself","body":"Write a thesis statement and ONE full P–E–E paragraph for:\n\n\"Should secondary students be required to study a second language?\"\n\nCheck your paragraph: does the explanation connect the evidence back to the thesis explicitly, or does it stop at the example?"},{"heading":"Summary","body":"• Take a clear position in a one-sentence thesis, and preview your reasons.\n• One point per paragraph: Point, Evidence, Explanation.\n• The explanation earns the marks — never leave the link implicit.\n• Concede a counter-argument honestly, then answer it.\n• Conclude by restating the position freshly; add no new evidence."}]'::jsonb, '[{"term":"Thesis statement","definition":"One sentence stating the position the essay will argue."},{"term":"Topic sentence","definition":"The opening sentence of a paragraph, naming its single main point."},{"term":"Counter-argument","definition":"An opposing view, acknowledged and then answered."},{"term":"Cohesion","definition":"The linking of ideas so writing flows logically."}]'::jsonb, 'liblearn', 'published', 1)
insert into public.lessons (id, topic_id, subject_id, curriculum_version_id, grade, title, estimated_minutes, objectives, sections, key_terms, provenance, review_status, sort_order) values
  ('g11-civics-government-l1', 'g11-civics-government', 'civics', 'liblearn-v1', 11, 'Constitutions and the Separation of Powers', 14, '[{"id":"o1","text":"Explain what a constitution is and what it does."},{"id":"o2","text":"Describe the three branches of government and their functions."},{"id":"o3","text":"Explain how checks and balances limit the abuse of power."}]'::jsonb, '[{"heading":"What you will learn","body":"What a constitution is for, why governmental power is deliberately divided, and how the branches restrain one another.\n\nA note on scope: this lesson teaches these CONCEPTS, which are shared across constitutional democracies. It does not set out the specific provisions of the Liberian Constitution. For those — the exact composition of the Legislature, terms of office, or particular articles — use the Constitution itself or your teacher’s materials. LibLearn will not state them from memory, because a detail misremembered here is a detail you would carry into an examination."},{"heading":"What a constitution does","body":"A constitution is the highest law of a state. Ordinary laws must conform to it, and where a law conflicts with the constitution, the constitution prevails.\n\nIt generally does four things:\n\n1. ESTABLISHES the institutions of government and their powers.\n2. LIMITS those powers, saying what government may NOT do.\n3. PROTECTS the rights of citizens.\n4. SETS THE PROCEDURE for its own amendment — usually a harder process than passing an ordinary law.\n\nPoint 2 deserves emphasis. A constitution is not only a description of how government works; it is a restraint upon it. The provisions protecting citizens are binding on those in office, which is the essence of the RULE OF LAW: those who govern are themselves subject to the law.\n\nPoint 4 matters too. Making amendment deliberately difficult stops a temporary majority from rewriting fundamental rules for short-term advantage."},{"heading":"The three branches","body":"Most constitutional democracies divide government into three branches, each with a distinct function:\n\nThe LEGISLATURE makes law. It debates and passes bills, approves taxation and public spending, and scrutinises the executive.\n\nThe EXECUTIVE carries out and enforces law. It runs government departments, conducts foreign relations, and administers public services day to day.\n\nThe JUDICIARY interprets law and resolves disputes. It applies law to particular cases and determines what the law means when that is contested.\n\nThe division is the point. If one body could make a law, enforce it, and judge disputes about it, there would be no protection against it acting arbitrarily — it would be judge in its own cause."},{"heading":"Checks and balances","body":"Separation alone is not enough; the branches also need power over one another. Typical checks include:\n\n• The legislature controls public money, so the executive cannot spend without approval.\n• The legislature can investigate and question the executive.\n• The executive may have a role in appointing judges, often requiring legislative confirmation.\n• Courts can rule that an action of government is unlawful or unconstitutional.\n• Amending the constitution requires a heightened procedure beyond one branch’s control.\n\nThe design principle: ambition is set against ambition. Rather than relying on officials to restrain themselves, the structure gives each branch both the means and the motive to resist overreach by the others.\n\nThis also explains why these arrangements can look slow. Deliberate friction is the mechanism working, not failing.","example":"Why control of money is such a powerful check:\n\nSuppose an executive wishes to create a new agency. It can propose it — but it cannot fund it without the legislature voting the money.\n\nSo the legislature can decline, or attach conditions, or demand reporting. Without ever directly commanding the executive, it constrains what the executive can actually do.\n\nThis is why the power to approve spending is among the oldest and most significant legislative powers: control of funding is control of action."},{"heading":"Try it yourself","body":"1. Explain in your own words why a constitution is harder to amend than an ordinary law.\n2. A government department spends money the legislature never approved. Which principle is breached, and which branch would you expect to respond?\n3. Give one argument FOR and one AGAINST the slowness that checks and balances produce.\n\nThen, using your Constitution or class materials, identify how these three branches are actually constituted in Liberia — and note anything that differs from the general pattern above."},{"heading":"Summary","body":"• A constitution is the highest law: it establishes, limits, protects and sets amendment procedure.\n• Rule of law means those who govern are also governed by law.\n• Legislature makes law, executive enforces it, judiciary interprets it.\n• Checks and balances give each branch the means to restrain the others.\n• Control of public money is among the strongest checks available.\n• Country-specific constitutional detail must come from the constitution itself, not from memory."}]'::jsonb, '[{"term":"Constitution","definition":"The fundamental law setting out how a state is governed and limiting the power of government."},{"term":"Separation of powers","definition":"Dividing government functions among separate branches so no one body holds all power."},{"term":"Checks and balances","definition":"Powers each branch holds to restrain the others."},{"term":"Rule of law","definition":"The principle that everyone, including those who govern, is subject to the law."}]'::jsonb, 'liblearn', 'published', 1)
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q-alg-1', 'g8-math-algebra', 'mathematics', 'liblearn-v1', 8, 'multiple_choice', 'What is the coefficient of x in the expression 7x + 4?', '["7","4","x","11"]'::jsonb, 0, 'The coefficient is the number multiplying the variable. In 7x, the 7 multiplies x, so the coefficient is 7. The 4 is a constant.', 'foundation', 'ljhsce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q-alg-2', 'g8-math-algebra', 'mathematics', 'liblearn-v1', 8, 'multiple_choice', 'Solve for x:  x + 9 = 16', '["x = 25","x = 7","x = 9","x = 16"]'::jsonb, 1, 'Nine has been added to x, so subtract 9 from both sides: x + 9 - 9 = 16 - 9, giving x = 7. Check: 7 + 9 = 16.', 'foundation', 'ljhsce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q-alg-3', 'g8-math-algebra', 'mathematics', 'liblearn-v1', 8, 'multiple_choice', 'Solve for x:  3x + 4 = 19', '["x = 5","x = 7","x = 15","x = 23"]'::jsonb, 0, 'Undo in reverse order. Subtract 4 from both sides: 3x = 15. Then divide both sides by 3: x = 5. Check: 3 x 5 + 4 = 19.', 'core', 'ljhsce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q-alg-4', 'g8-math-algebra', 'mathematics', 'liblearn-v1', 8, 'multiple_choice', 'Expand:  4(x + 3)', '["4x + 3","4x + 12","x + 12","7x"]'::jsonb, 1, 'The 4 multiplies every term inside the bracket, not just the first: 4 times x is 4x, and 4 times 3 is 12. So the answer is 4x + 12.', 'core', 'ljhsce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q-alg-5', 'g8-math-algebra', 'mathematics', 'liblearn-v1', 8, 'multiple_choice', 'Solve for x:  2(x - 5) = 14', '["x = 2","x = 9","x = 12","x = 24"]'::jsonb, 2, 'Expand first: 2x - 10 = 14. Add 10 to both sides: 2x = 24. Divide by 2: x = 12. Check: 2(12 - 5) = 2 x 7 = 14.', 'challenge', 'ljhsce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q-alg-6', 'g8-math-algebra', 'mathematics', 'liblearn-v1', 8, 'multiple_choice', 'A taxi charges 40 dollars to start plus 15 dollars per kilometre. Which expression gives the cost of a journey of k kilometres?', '["40k + 15","55k","40 + 15k","15 + 40k"]'::jsonb, 2, 'The 40 is paid once, so it stands alone. The 15 is paid for each kilometre, so it multiplies k. That gives 40 + 15k.', 'core', null, 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q-alg-7', 'g8-math-algebra', 'mathematics', 'liblearn-v1', 8, 'multiple_choice', 'Solve for x:  5x - 3 = 2x + 12', '["x = 3","x = 5","x = 9","x = 15"]'::jsonb, 1, 'Collect the x terms on one side: subtract 2x from both sides to get 3x - 3 = 12. Add 3: 3x = 15. Divide by 3: x = 5.', 'challenge', 'ljhsce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q-fr8-1', 'g8-math-fractions', 'mathematics', 'liblearn-v1', 8, 'multiple_choice', 'Write 3/4 as a decimal.', '["0.34","0.75","0.43","1.33"]'::jsonb, 1, 'A fraction means divide. 3 divided by 4 is 0.75.', 'foundation', null, 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q-fr8-2', 'g8-math-fractions', 'mathematics', 'liblearn-v1', 8, 'multiple_choice', 'Write 0.35 as a fraction in its lowest terms.', '["35/10","7/20","3/5","35/1000"]'::jsonb, 1, '0.35 is thirty-five hundredths, so 35/100. Divide top and bottom by 5 to get 7/20.', 'core', null, 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q-fr8-3', 'g8-math-fractions', 'mathematics', 'liblearn-v1', 8, 'multiple_choice', 'Which is larger: 0.6 or 5/8?', '["0.6","5/8","They are equal","Cannot be compared"]'::jsonb, 1, 'Convert 5/8 to a decimal: 5 divided by 8 is 0.625. Since 0.625 is greater than 0.6, the fraction 5/8 is larger.', 'core', null, 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q-fr6-1', 'g6-math-fractions', 'mathematics', 'liblearn-v1', 6, 'multiple_choice', 'In the fraction 3/8, which number is the denominator?', '["3","8","Both","Neither"]'::jsonb, 1, 'The denominator is the bottom number. It tells you how many equal parts the whole was cut into - here, 8.', 'foundation', 'lpsce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q-fr6-2', 'g6-math-fractions', 'mathematics', 'liblearn-v1', 6, 'multiple_choice', 'Which fraction is larger: 5/8 or 3/8?', '["5/8","3/8","They are equal","It depends"]'::jsonb, 0, 'The denominators match, so the pieces are the same size. Five pieces is more than three, so 5/8 is larger.', 'foundation', 'lpsce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q-fr6-3', 'g6-math-fractions', 'mathematics', 'liblearn-v1', 6, 'multiple_choice', 'A loaf is cut into 8 equal slices. You take 3. What fraction of the loaf is left?', '["3/8","5/8","8/3","1/8"]'::jsonb, 1, 'Eight slices in total, three taken, so five remain. That is 5/8 of the loaf.', 'core', 'lpsce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q-mat-1', 'g8-science-matter', 'general-science', 'liblearn-v1', 8, 'multiple_choice', 'In which state of matter are the particles packed closely in a fixed pattern?', '["Solid","Liquid","Gas","All three"]'::jsonb, 0, 'In a solid the particles hold fixed positions and can only vibrate. That is why a solid keeps its own shape.', 'foundation', 'ljhsce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q-mat-2', 'g8-science-matter', 'general-science', 'liblearn-v1', 8, 'multiple_choice', 'Why does a gas fill its whole container?', '["Its particles are heavier than liquid particles","Its particles are far apart and move freely in all directions","Its particles are joined in a fixed pattern","Gases have no particles"]'::jsonb, 1, 'Gas particles are widely spaced and move quickly in every direction, so they spread out until they occupy the whole space available.', 'core', 'ljhsce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q-mat-3', 'g8-science-matter', 'general-science', 'liblearn-v1', 8, 'multiple_choice', 'Which state keeps its volume but takes the shape of its container?', '["Solid","Liquid","Gas","None of them"]'::jsonb, 1, 'Liquid particles stay close together, so the volume is fixed, but they slide past one another, so the shape changes to fit the container.', 'core', null, 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q-eng-1', 'g8-english-speech', 'english', 'liblearn-v1', 8, 'multiple_choice', 'In "The clever student answered quickly", which word is the adjective?', '["student","answered","clever","quickly"]'::jsonb, 2, 'An adjective describes a noun. "Clever" describes the student, so it is the adjective. "Quickly" describes the verb, which makes it an adverb.', 'foundation', 'ljhsce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q-eng-2', 'g8-english-speech', 'english', 'liblearn-v1', 8, 'multiple_choice', 'Identify the verb in "The farmer harvested the rice before the rain."', '["farmer","harvested","rice","rain"]'::jsonb, 1, 'The verb tells you what is being done. The farmer harvested - that action is the verb.', 'core', 'ljhsce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q-cell-1', 'g10-bio-cells', 'biology', 'liblearn-v1', 10, 'multiple_choice', 'Which organelle controls the activities of the cell?', '["Mitochondrion","Nucleus","Cell membrane","Vacuole"]'::jsonb, 1, 'The nucleus holds the genetic information and directs the cell’s activities.', 'foundation', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q-cell-2', 'g10-bio-cells', 'biology', 'liblearn-v1', 10, 'multiple_choice', 'Which THREE structures are found in plant cells but not animal cells?', '["Nucleus, cytoplasm, membrane","Cell wall, chloroplast, permanent vacuole","Mitochondria, ribosomes, nucleus","Chloroplast, nucleus, mitochondria"]'::jsonb, 1, 'Plant cells have a cellulose cell wall, chloroplasts for photosynthesis, and a large permanent vacuole. Animal cells have none of these three.', 'core', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q-cell-3', 'g10-bio-cells', 'biology', 'liblearn-v1', 10, 'multiple_choice', 'Muscle cells contain unusually large numbers of mitochondria. Why?', '["They need to store more genetic material","They require a great deal of energy to contract","They carry out photosynthesis","They must keep their shape rigid"]'::jsonb, 1, 'Mitochondria release energy through respiration. Contracting a muscle demands much energy, so muscle cells carry many of them.', 'challenge', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-quad-1', 'g11-math-quadratics', 'mathematics', 'liblearn-v1', 11, 'multiple_choice', 'Which of these is a quadratic equation in standard form?', '["3x + 5 = 0","x² + 2x − 8 = 0","x³ − 1 = 0","2/x = 4"]'::jsonb, 1, 'Standard form is ax² + bx + c = 0: the highest power of x must be exactly 2, and everything must be on one side. 3x + 5 = 0 is linear (highest power 1), x³ − 1 = 0 is cubic, and 2/x = 4 has x in the denominator, so it is not a polynomial equation at all.', 'foundation', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-quad-2', 'g11-math-quadratics', 'mathematics', 'liblearn-v1', 11, 'multiple_choice', 'Factorise:  x² + 5x + 6', '["(x + 1)(x + 6)","(x + 2)(x + 3)","(x − 2)(x − 3)","(x + 5)(x + 6)"]'::jsonb, 1, 'You need two numbers that multiply to 6 and add to 5. Check the pairs: 1 and 6 multiply to 6 but add to 7. 2 and 3 multiply to 6 and add to 5 — correct. So the factors are (x + 2)(x + 3). Expanding back gives x² + 3x + 2x + 6 = x² + 5x + 6.', 'core', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-quad-3', 'g11-math-quadratics', 'mathematics', 'liblearn-v1', 11, 'multiple_choice', 'The equation (x + 4)(x − 2) = 0 has which solutions?', '["x = 4 or x = −2","x = −4 or x = 2","x = 4 or x = 2","x = −4 or x = −2"]'::jsonb, 1, 'Set each bracket to zero separately. From x + 4 = 0 you get x = −4. From x − 2 = 0 you get x = 2. Note the sign flips: the bracket (x + 4) gives the root −4, not +4. Reading the numbers straight out of the brackets is the most common error here.', 'core', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-quad-4', 'g11-math-quadratics', 'mathematics', 'liblearn-v1', 11, 'multiple_choice', 'For 2x² − 7x + 3 = 0, what is the value of the discriminant b² − 4ac?', '["25","73","−25","49"]'::jsonb, 0, 'Here a = 2, b = −7 and c = 3. So b² − 4ac = (−7)² − 4(2)(3) = 49 − 24 = 25. Keeping the minus sign on b matters, though in this case squaring removes it. Since 25 is positive, the equation has two different real roots.', 'core', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-quad-5', 'g11-math-quadratics', 'mathematics', 'liblearn-v1', 11, 'multiple_choice', 'How many real roots does x² + 2x + 5 = 0 have?', '["Two","One","None","Cannot be determined"]'::jsonb, 2, 'Find the discriminant: b² − 4ac = 2² − 4(1)(5) = 4 − 20 = −16. It is negative, and a negative number has no real square root, so the formula produces no real answer. The equation has no real roots — its graph never crosses the x-axis. You can answer this without solving anything.', 'challenge', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-trig-1', 'g11-math-trigonometry', 'mathematics', 'liblearn-v1', 11, 'multiple_choice', 'In a right-angled triangle, which side is always the hypotenuse?', '["The side opposite the right angle","The side adjacent to the chosen angle","The shortest side","The vertical side"]'::jsonb, 0, 'The hypotenuse is always opposite the right angle, and it is always the longest side. Unlike "opposite" and "adjacent", which swap depending on which angle you are working from, the hypotenuse never changes.', 'foundation', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-trig-2', 'g11-math-trigonometry', 'mathematics', 'liblearn-v1', 11, 'multiple_choice', 'You know the hypotenuse and want the side opposite a given angle. Which ratio should you use?', '["Cosine","Sine","Tangent","Pythagoras"]'::jsonb, 1, 'SOH-CAH-TOA: sine links Opposite and Hypotenuse, which are exactly the two sides involved. Cosine uses adjacent and hypotenuse; tangent uses opposite and adjacent. Pick the ratio containing the side you know and the side you want.', 'core', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-trig-3', 'g11-math-trigonometry', 'mathematics', 'liblearn-v1', 11, 'multiple_choice', 'A ramp rises 3 m over a horizontal distance of 4 m. What is tan of the angle it makes with the ground?', '["0.75","1.33","0.6","0.8"]'::jsonb, 0, 'tan = opposite / adjacent. The rise (3 m) is opposite the angle and the horizontal distance (4 m) is adjacent, so tan θ = 3/4 = 0.75. Dividing the wrong way round gives 1.33, which is the tangent of the other angle in the triangle.', 'core', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-photo-1', 'g11-bio-photosynthesis', 'biology', 'liblearn-v1', 11, 'multiple_choice', 'Which are the raw materials for photosynthesis?', '["Glucose and oxygen","Carbon dioxide and water","Oxygen and water","Glucose and carbon dioxide"]'::jsonb, 1, 'The equation is 6CO₂ + 6H₂O → C₆H₁₂O₆ + 6O₂. Carbon dioxide and water go in; glucose and oxygen come out. Glucose and oxygen are the PRODUCTS — reversing them is the most common slip, and it describes respiration instead.', 'foundation', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-photo-2', 'g11-bio-photosynthesis', 'biology', 'liblearn-v1', 11, 'multiple_choice', 'Why is chlorophyll written above the arrow in the equation rather than as a reactant?', '["It is used up during the reaction","It absorbs light energy but is not consumed","It is a product of the reaction","It only acts at night"]'::jsonb, 1, 'Chlorophyll captures light energy so the reaction can proceed, but it is not used up and does not end up in the glucose. The same is true of light itself. Substances written above the arrow enable the reaction without being consumed by it.', 'core', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-photo-3', 'g11-bio-photosynthesis', 'biology', 'liblearn-v1', 11, 'multiple_choice', 'A graph of photosynthesis rate against light intensity rises then levels off. What does the flat section show?', '["The plant has stopped photosynthesising","Light is still the limiting factor","Another factor, such as CO₂ or temperature, has become limiting","The chlorophyll has been used up"]'::jsonb, 2, 'While the line rises, light is limiting — more light gives more rate. Once it plateaus, adding light changes nothing, so something else is now the constraint, usually CO₂ concentration or temperature. The plant is still photosynthesising, just capped by a different factor. Answering "it has enough light" does not name the limiting factor and loses marks.', 'challenge', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-photo-4', 'g11-bio-photosynthesis', 'biology', 'liblearn-v1', 11, 'multiple_choice', 'Unlike light intensity, raising temperature well past the optimum makes the rate FALL. Why?', '["Carbon dioxide dissolves less readily","Enzymes denature and lose their shape","Chlorophyll changes colour","The stomata close permanently"]'::jsonb, 1, 'Photosynthesis is enzyme-controlled, and enzymes are proteins. Excess heat changes the shape of the active site permanently, so reactions slow sharply. This is why the temperature curve peaks and falls, while light and CO₂ curves simply level off — a distinction examiners test often.', 'challenge', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-gen-1', 'g11-bio-genetics', 'biology', 'liblearn-v1', 11, 'multiple_choice', 'What is the difference between genotype and phenotype?', '["Genotype is the alleles carried; phenotype is the characteristic shown","Genotype is what you see; phenotype is the DNA","They mean the same thing","Genotype applies to plants, phenotype to animals"]'::jsonb, 0, 'Genotype is the pair of alleles an organism carries, such as Tt. Phenotype is the characteristic that results, such as "tall". The distinction matters because TT and Tt give the same phenotype but behave differently when bred.', 'foundation', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-gen-2', 'g11-bio-genetics', 'biology', 'liblearn-v1', 11, 'multiple_choice', 'Crossing two heterozygous plants (Tt × Tt) gives what phenotype ratio?', '["1 tall : 1 short","3 tall : 1 short","All tall","1 tall : 3 short"]'::jsonb, 1, 'The Punnett square gives TT, Tt, Tt and tt. The first three all contain at least one dominant T, so they are tall; only tt is short. That is 3 tall : 1 short. The genotype ratio is different — 1 TT : 2 Tt : 1 tt — so read carefully which ratio the question wants.', 'core', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-gen-3', 'g11-bio-genetics', 'biology', 'liblearn-v1', 11, 'multiple_choice', 'A tall plant crossed with a short plant (tt) produces about half tall and half short offspring. What is the tall parent’s genotype?', '["TT","Tt","tt","Impossible to tell"]'::jsonb, 1, 'If the tall parent were TT, every offspring would inherit a T and all would be tall. Getting roughly half short means the tall parent must carry a recessive allele to pass on, so it is Tt. Tt × tt gives a 1:1 ratio, which is exactly what was observed.', 'challenge', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-mole-1', 'g11-chem-mole', 'chemistry', 'liblearn-v1', 11, 'multiple_choice', 'How many particles are in one mole of a substance?', '["6.02 × 10²³","6.02 × 10²²","1 × 10²³","3.01 × 10²³"]'::jsonb, 0, 'One mole contains 6.02 × 10²³ particles — Avogadro’s constant. It is a counting unit for very large numbers, in the same way a dozen is a counting unit for twelve.', 'foundation', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-mole-2', 'g11-chem-mole', 'chemistry', 'liblearn-v1', 11, 'multiple_choice', 'What is the molar mass of CO₂?  (C = 12, O = 16)', '["28 g/mol","44 g/mol","32 g/mol","56 g/mol"]'::jsonb, 1, 'Add the atomic masses in the formula: carbon contributes 12, and there are two oxygens contributing 2 × 16 = 32. So 12 + 32 = 44 g/mol. Choosing 28 means only one oxygen was counted.', 'core', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-mole-3', 'g11-chem-mole', 'chemistry', 'liblearn-v1', 11, 'multiple_choice', 'How many moles are in 36 g of water, H₂O?  (H = 1, O = 16)', '["1 mol","2 mol","0.5 mol","18 mol"]'::jsonb, 1, 'Molar mass of H₂O = (2 × 1) + 16 = 18 g/mol. Then moles = mass / molar mass = 36 / 18 = 2 mol. A quick sanity check: 36 g is twice 18 g, so 2 moles.', 'core', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-mole-4', 'g11-chem-mole', 'chemistry', 'liblearn-v1', 11, 'multiple_choice', 'A sample of 0.1 mol of a gas has a mass of 4.4 g. What is its molar mass?', '["4.4 g/mol","44 g/mol","0.44 g/mol","440 g/mol"]'::jsonb, 1, 'Rearrange the key equation: molar mass = mass / moles = 4.4 / 0.1 = 44 g/mol. Dividing by 0.1 multiplies by 10, which trips people up. A molar mass of 44 g/mol suggests the gas is carbon dioxide.', 'challenge', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-bond-1', 'g11-chem-bonding', 'chemistry', 'liblearn-v1', 11, 'multiple_choice', 'What type of bonding forms between a metal and a non-metal?', '["Covalent","Ionic","Metallic","No bond forms"]'::jsonb, 1, 'A metal loses electrons to form a positive ion and a non-metal gains them to form a negative ion. The opposite charges attract, which is ionic bonding. Covalent bonding is sharing, and happens between two non-metals.', 'foundation', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-bond-2', 'g11-chem-bonding', 'chemistry', 'liblearn-v1', 11, 'multiple_choice', 'Why does solid sodium chloride not conduct electricity, while molten sodium chloride does?', '["The ions are destroyed when solid","The ions are fixed in the lattice when solid and free to move when molten","Solid NaCl contains no ions","Melting converts the bonding to covalent"]'::jsonb, 1, 'Conduction needs charged particles that are free to move. The ions exist in both states, but in the solid lattice they are locked in position. Melting frees them, so the liquid conducts. The ions are neither destroyed nor changed — only their mobility changes.', 'core', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-bond-3', 'g11-chem-bonding', 'chemistry', 'liblearn-v1', 11, 'multiple_choice', 'When water boils, what is actually broken?', '["The O–H covalent bonds inside each molecule","The forces of attraction between separate water molecules","Both equally","The oxygen atoms split apart"]'::jsonb, 1, 'Boiling separates whole molecules from one another by overcoming the weak forces between them. The strong covalent O–H bonds inside each molecule survive, which is why steam is still H₂O rather than hydrogen and oxygen gas. Melting and boiling points tell you about forces BETWEEN particles, not bonds within them.', 'challenge', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-motion-1', 'g11-phys-motion', 'physics', 'liblearn-v1', 11, 'multiple_choice', 'A book rests on a table without moving. What is the resultant force on it?', '["Equal to its weight","Zero","Upward","Downward"]'::jsonb, 1, 'Gravity pulls the book down and the table pushes up with an equal force, so the two cancel and the resultant is zero. By Newton’s first law, zero resultant force means no change in motion — the book stays at rest. Forces acting does not mean a resultant force.', 'foundation', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-motion-2', 'g11-phys-motion', 'physics', 'liblearn-v1', 11, 'multiple_choice', 'A 1200 kg car has a 3600 N driving force and 600 N of resistance. What is its acceleration?', '["3.0 m/s²","2.5 m/s²","0.5 m/s²","3.5 m/s²"]'::jsonb, 1, 'Find the RESULTANT force first: 3600 − 600 = 3000 N. Then a = F/m = 3000/1200 = 2.5 m/s². Using the 3600 N driving force alone gives 3.0 m/s² — a wrong answer that looks plausible, which is why the resultant step must be written down explicitly.', 'core', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-motion-3', 'g11-phys-motion', 'physics', 'liblearn-v1', 11, 'multiple_choice', 'A book rests on a table. Are "gravity pulling the book down" and "the table pushing the book up" an action–reaction pair?', '["Yes, they are equal and opposite","No, because they both act on the same object","Yes, because the book is not moving","No, because gravity is not a real force"]'::jsonb, 1, 'Action–reaction pairs act on DIFFERENT objects. Both of these forces act on the book, so they are balanced forces under the first law, not a third-law pair. The genuine partner to "the table pushes up on the book" is "the book pushes down on the table". Being equal and opposite is not sufficient.', 'challenge', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-elec-1', 'g11-phys-electricity', 'physics', 'liblearn-v1', 11, 'multiple_choice', 'A 12 V supply drives current through a 4 Ω resistor. What is the current?', '["48 A","3 A","0.33 A","16 A"]'::jsonb, 1, 'Rearrange V = IR to I = V/R = 12/4 = 3 A. Multiplying instead of dividing gives 48 A, which should look obviously too large for a 12 V supply — checking whether an answer is physically sensible catches this immediately.', 'foundation', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-elec-2', 'g11-phys-electricity', 'physics', 'liblearn-v1', 11, 'multiple_choice', 'In a series circuit, which quantity is the same at every point?', '["Voltage","Current","Resistance","Power"]'::jsonb, 1, 'A series circuit has one single path, so charge has nowhere else to go and the current is identical everywhere. Voltage is what divides between the components, adding up to the supply voltage. In a PARALLEL circuit the opposite holds: voltage is shared, current divides.', 'core', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-elec-3', 'g11-phys-electricity', 'physics', 'liblearn-v1', 11, 'multiple_choice', 'Adding a second resistor in PARALLEL to a circuit has what effect on total resistance?', '["It increases, because there is more resistance in total","It decreases, because current has an additional path","It stays the same","It doubles"]'::jsonb, 1, 'This is counter-intuitive but important: an extra parallel branch gives current another route, so more total current flows for the same voltage, which means total resistance has fallen. The total is always LESS than the smallest individual resistance. Resistances only add in series.', 'challenge', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-essay-1', 'g11-eng-essay', 'english', 'liblearn-v1', 11, 'multiple_choice', 'Which is the strongest thesis statement?', '["This essay will discuss school uniforms.","School uniforms are an interesting topic with many opinions.","School uniforms should be required because they reduce visible inequality, lower family costs and cut distraction.","There are advantages and disadvantages to school uniforms."]'::jsonb, 2, 'A thesis must take a POSITION, not announce a subject. Only the third option states what the writer will argue and previews the three supporting reasons, which then become the three body paragraphs. The others describe the topic without committing to a view.', 'foundation', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-essay-2', 'g11-eng-essay', 'english', 'liblearn-v1', 11, 'multiple_choice', 'In the P–E–E structure, which part do students most often leave out, losing marks?', '["Point","Evidence","Explanation","The topic sentence"]'::jsonb, 2, 'Students commonly state a point and give an example, then move on — leaving the reader to work out how the evidence proves the argument. The explanation is where the reasoning is actually demonstrated, so it is where most marks are awarded. Make the link explicit and connect it back to the thesis.', 'core', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-essay-3', 'g11-eng-essay', 'english', 'liblearn-v1', 11, 'multiple_choice', 'What is the correct way to handle a counter-argument?', '["Ignore it so your argument looks stronger","State it and leave it, to appear balanced","Acknowledge it genuinely, then answer it","Put it in the conclusion"]'::jsonb, 2, 'Acknowledging an opposing view shows you have considered the whole question, which strengthens your case — but only if you then ANSWER it. Conceding without answering argues against yourself, and ignoring it leaves an obvious gap. Present the opposing view fairly rather than as a weak version.', 'core', 'wassce', 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-civ-1', 'g11-civics-government', 'civics', 'liblearn-v1', 11, 'multiple_choice', 'Which branch of government is responsible for interpreting the law?', '["The legislature","The executive","The judiciary","The civil service"]'::jsonb, 2, 'The judiciary interprets law and resolves disputes about what it means. The legislature makes law and the executive enforces it. Separating these three functions prevents any one body from making a law, enforcing it, and judging disputes about it.', 'foundation', null, 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-civ-2', 'g11-civics-government', 'civics', 'liblearn-v1', 11, 'multiple_choice', 'Why is a constitution usually harder to amend than an ordinary law?', '["Because it is a longer document","To stop a temporary majority rewriting fundamental rules for short-term advantage","Because only judges may amend it","Because it never needs changing"]'::jsonb, 1, 'A constitution sets the fundamental rules and limits on government power. Requiring a heightened procedure to change it means those rules cannot be swept aside by whoever happens to hold a majority at one moment. Constitutions can and do change — the process is simply made deliberately demanding.', 'core', null, 'liblearn', 'published')
insert into public.questions (id, topic_id, subject_id, curriculum_version_id, grade, question_type, question_text, options, correct_answer, explanation, difficulty, exam_goal, provenance, review_status) values
  ('q11-civ-3', 'g11-civics-government', 'civics', 'liblearn-v1', 11, 'multiple_choice', 'Why is legislative control over public spending considered such a powerful check on the executive?', '["Because the legislature can arrest officials","Because the executive cannot act on plans it has no funds for","Because it allows the legislature to appoint judges","Because it transfers executive powers to the legislature"]'::jsonb, 1, 'The legislature need not command the executive directly. By approving, refusing or attaching conditions to funding, it controls what the executive can actually carry out — since a plan without money cannot be implemented. This is why the power to approve spending is among the oldest and most significant legislative powers.', 'challenge', null, 'liblearn', 'published')
